package com.truckload.controller;
import android.Manifest;
import android.app.*;
import android.bluetooth.BluetoothAdapter;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.os.*;
import android.text.*;
import android.widget.*;
import java.util.*;

/** Palette, quick actions, calibration guidance and bounded foreground reconnect. */
final class V4Panels {
 private final MainActivity a;private final Telemetry m;private final BleClient ble;
 private final Handler handler=new Handler(Looper.getMainLooper());
 private TextView status,compat,diagnostics,wizardStatus;private Button work,wizardCapture,wizardEnable;
 private final List<Button> zones=new ArrayList<>(),testColors=new ArrayList<>();
 private long sensorAt,telemetryAt,gpsAt,lightsAt,benchAt;private String phase="Disconnected",pendingWork=null;
 private long workSent;private boolean foreground=false,manualStop=false,connecting=false,retrying=false,closed=false;
 private int attempt=0;private Runnable retry;private AlertDialog wizard;private EditText known;
 private String wizardTrailer="",pendingTrailer="";private double lastCaptured=Double.NaN,pendingPsi=Double.NaN;private boolean capturePending=false;private long captureSent;
 private final BroadcastReceiver radio=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(i.getIntExtra(BluetoothAdapter.EXTRA_STATE,-1)==BluetoothAdapter.STATE_ON){attempt=0;schedule();}}};
 V4Panels(MainActivity activity,Telemetry model,BleClient client){a=activity;m=model;ble=client;IntentFilter filter=new IntentFilter(BluetoothAdapter.ACTION_STATE_CHANGED);if(Build.VERSION.SDK_INT>=33)a.registerReceiver(radio,filter,Context.RECEIVER_EXPORTED);else a.registerReceiver(radio,filter);}
 private long now(){return SystemClock.elapsedRealtime();}
 private boolean fresh(long t){return a.isConnected()&&SessionPolicy.fresh(now(),t);}
 private boolean permitted(){String[] permissions=Build.VERSION.SDK_INT>=31?new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT}:new String[]{Manifest.permission.ACCESS_FINE_LOCATION};for(String p:permissions)if(a.checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)return false;return true;}
 private void cancelRetry(){if(retry!=null)handler.removeCallbacks(retry);retry=null;}
 void manual(){manualStop=true;retrying=false;cancelRetry();}
 private void schedule(){if(closed||!foreground||manualStop||a.isConnected()||connecting||retry!=null||!permitted())return;String address=a.getPreferences(0).getString("lastHeltec","");long delay=SessionPolicy.retryDelay(attempt);if(address.isEmpty()||delay<0)return;try{if(!ble.enabled())return;}catch(RuntimeException e){return;}retrying=true;phase="Reconnecting";retry=()->{retry=null;if(closed||!foreground||manualStop||!permitted())return;try{if(!ble.enabled()){retrying=false;phase="Bluetooth off";update();return;}attempt++;ble.reconnect(address);}catch(RuntimeException e){retrying=false;phase="Disconnected";schedule();}update();};handler.postDelayed(retry,delay);}
 void active(boolean active){foreground=active;if(active){if(!manualStop){attempt=0;schedule();}}else{cancelRetry();if(retrying&&connecting)ble.disconnect();retrying=false;}update();}
 void connection(int state,String message){connecting=state==BleClient.CONNECTING||state==BleClient.SCANNING;phase=state==BleClient.READY?"Connected":state==BleClient.CONNECTING?retrying?"Reconnecting":"Connecting":state==BleClient.SCANNING?"Searching":"Disconnected";
  if(state==BleClient.READY){String address=ble.address();if(address!=null)a.getPreferences(0).edit().putString("lastHeltec",address).apply();manualStop=false;retrying=false;attempt=0;cancelRetry();}
  if(state!=BleClient.READY){sensorAt=telemetryAt=gpsAt=lightsAt=benchAt=0;pendingWork=null;capturePending=false;}
  if(state==BleClient.OFF){handler.post(()->{schedule();update();});}
 }
 void record(String type,String line){long t=now();if(type.equals("SENSOR"))sensorAt=t;if(type.equals("T"))telemetryAt=t;if(type.equals("GPS"))gpsAt=t;if(type.equals("BENCH_STATE"))benchAt=t;if(type.equals("LIGHT_STATE")){lightsAt=t;if(pendingWork!=null&&m.lightMode.equals(pendingWork))pendingWork=null;}
  if(type.equals("ERR")&&line.contains("WORK_LIGHT"))pendingWork=null;
  if(capturePending&&line.equals("OK|CAL_CAPTURE")){if(m.profile.equals(pendingTrailer)){lastCaptured=pendingPsi;wizardTrailer=pendingTrailer;}capturePending=false;a.notice("Calibration point saved. Add another at a different pressure, or verify the load.");}
  if(type.equals("ERR")&&line.contains("CAL_CAPTURE"))capturePending=false;
 }
 boolean canCapture(){return SessionPolicy.capture(m,a.isConnected(),now(),sensorAt,telemetryAt)&&(!m.extended||fresh(benchAt));}
 void overview(LinearLayout p){LinearLayout c=a.card(p,"Device status",null);status=a.text("Bluetooth: Disconnected\nSensor: Unknown\nGPS: Unknown",13,0xffedf3fa);c.addView(status);compat=a.text("App 0.7.0 · connect to check controller",12,0xffa2b1c4);work=a.button("Work lights · status unavailable",()->{if(m.bench){a.notice("Stop bench mode first.");return;}pendingWork=m.lightMode.equals("WORK")?"LOAD":"WORK";workSent=now();a.send("WORK_LIGHT|"+(pendingWork.equals("WORK")?"ON":"OFF"));update();},false);work.setTextSize(18);work.setMinHeight(a.dp(64));a.addButton(p,work);a.gap(p,12);}
 void chooseTrailer(){if(!a.isConnected()){a.notice("Connect the Heltec first.");return;}if(m.bench){a.notice("Stop bench mode before switching trailers.");return;}if(m.profiles.isEmpty()){a.notice("No saved trailers. Add one in Trailers.");a.showTab(1);return;}String[] names=new String[m.profiles.size()];for(int i=0;i<names.length;i++)names[i]=m.profiles.get(i).name;new AlertDialog.Builder(a).setTitle("Select trailer · "+m.profile).setItems(names,(d,i)->{if(!a.isConnected()||m.bench){a.notice("Connect and exit bench mode first.");return;}a.send("PROFILE_SELECT|"+names[i]);}).setNegativeButton("Cancel",null).show();}
 void colorDialog(int index){LinearLayout p=a.vertical();p.setPadding(a.dp(18),a.dp(10),a.dp(18),a.dp(10));String saved=m.colors.get(Telemetry.MODES[index]);p.addView(a.text("Saved on controller: #"+saved+"\nSelect a swatch, then Save. Lighting mode stays unchanged.",12,0xffa2b1c4));TextView preview=a.text("",18,Color.WHITE);preview.setGravity(17);p.addView(preview,new LinearLayout.LayoutParams(-1,a.dp(64)));String[] names={"Red","Orange","Amber","Yellow","Green","Mint","Cyan","Light blue","Blue","Purple","Magenta","Pink","White","Gray","Warm white","Black"};String[] values={"FF0000","FF6600","FFBF00","FFFF00","00FF00","54D6B4","00FFFF","66BBFF","0000FF","8000FF","FF00FF","FF80AB","FFFFFF","808080","FFD9A3","000000"};List<Button> swatches=new ArrayList<>();EditText hex=new EditText(a);hex.setTextColor(0xffedf3fa);hex.setSingleLine(true);hex.setHint("6-digit hex, e.g. 54D6B4");hex.setFilters(new InputFilter[]{new InputFilter.LengthFilter(7)});
  Runnable refresh=()->{String h=hex.getText().toString().replace("#","").toUpperCase(Locale.US);if(!Telemetry.validHex(h)){preview.setText("Enter a six-digit color");return;}int color=Color.parseColor("#"+h);preview.setText("Selected #"+h);preview.setBackground(a.shape(color,0xff54d6b4,10));preview.setTextColor(Color.red(color)*299+Color.green(color)*587+Color.blue(color)*114>128000?0xff0b1420:Color.WHITE);for(int i=0;i<swatches.size();i++){Button b=swatches.get(i);b.setText((values[i].equals(h)?"✓ ":"")+names[i]);b.setBackground(a.shape(Color.parseColor("#"+values[i]),values[i].equals(h)?Color.WHITE:0xff2a3b52,8));b.setSelected(values[i].equals(h));}};
  for(int row=0;row<4;row++){LinearLayout line=a.row();for(int col=0;col<4;col++){final int i=row*4+col;Button b=a.button(names[i],()->hex.setText(values[i]),false);b.setTextSize(10);int c=Color.parseColor("#"+values[i]);b.setTextColor(Color.red(c)*299+Color.green(c)*587+Color.blue(c)*114>128000?0xff0b1420:Color.WHITE);b.setContentDescription(names[i]+" #"+values[i]);swatches.add(b);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,a.dp(52),1);lp.setMargins(a.dp(2),a.dp(3),a.dp(2),a.dp(3));line.addView(b,lp);}p.addView(line);}p.addView(a.text("Custom hexadecimal color",12,0xffa2b1c4));p.addView(hex);hex.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){refresh.run();}public void afterTextChanged(Editable e){}});hex.setText(saved);ScrollView wrap=new ScrollView(a);wrap.addView(p);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(Telemetry.COLOR_NAMES[index]).setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Save to Heltec",null).create();dialog.setOnShowListener(d->{dialog.getButton(-1).setEnabled(a.isConnected()&&(index!=6||m.extended));dialog.getButton(-1).setOnClickListener(v->{String h=hex.getText().toString().replace("#","").toUpperCase(Locale.US);if(!Telemetry.validHex(h)){hex.setError("Enter six hexadecimal digits");return;}if(!a.isConnected()||(index==6&&!m.extended)){a.notice("Connect compatible firmware first.");return;}a.send(index==6?"SET_DRIVE_COLOR2|"+h:"SET_LED_COLOR|"+Telemetry.MODES[index]+"|"+h);dialog.dismiss();});});dialog.show();}
 void bench(LinearLayout p){zones.clear();testColors.clear();a.gap(p,12);p.addView(a.text("Physical LED zones · GPIO43 / GPIO44",16,0xffedf3fa));String[] titles={"Both zones","Zone 1 · GPIO43","Zone 2 · GPIO44"},codes={"BOTH","1","2"};for(int i=0;i<3;i++){final int k=i;Button b=a.button(titles[i],()->{if(a.isConnected()&&m.bench&&m.capabilities.contains("BENCH_ZONES"))a.send("BENCH_ZONE|"+codes[k]);},false);zones.add(b);a.addButton(p,b);}p.addView(a.text("Firmware 0.6.1 supports both zones together. Individual zones and direct colors require BENCH_ZONES / BENCH_COLOR support. On firmware 0.6.4, White uses the dedicated white channel with WRGB output.",12,0xffa2b1c4));String[] colors={"OFF","RED","GREEN","BLUE","WHITE"};for(String color:colors){Button b=a.button("Test "+(color.equals("WHITE")?"white · RGBW conversion":color.toLowerCase(Locale.US)),()->{if(a.isConnected()&&m.bench&&m.capabilities.contains("BENCH_COLOR"))a.send("BENCH_COLOR|"+color);},false);testColors.add(b);a.addButton(p,b);}diagnostics=a.text("Diagnostics",12,0xffa2b1c4);p.addView(diagnostics);}
 void controllerDetails(LinearLayout p){p.addView(compat);}
 void diagnostics(){if(diagnostics==null)return;String current=a.isConnected()?m.firmware:"Unavailable";diagnostics.setText("App: 0.7.0\nController firmware: "+current+"\n"+(a.isConnected()?SessionPolicy.compatibility(m):"Connect to check compatibility")+"\nRaw ADC counts: "+(fresh(sensorAt)&&m.rawAdc>=0?m.rawAdc:"Unavailable")+"\nDivided ADC voltage: "+value(m.adcVolts,3,sensorAt)+" V\nReconstructed sensor voltage: "+value(m.sensorVolts,3,sensorAt)+" V\nReal filtered pressure: "+value(m.psi,1,telemetryAt)+" PSI\nBLE RSSI: unavailable\nLED zones: "+(a.isConnected()&&m.capabilities.contains("BENCH_ZONES")?"independent; selected "+m.benchZone:"both together only / not reported")+"\nTest color: "+(a.isConnected()&&m.capabilities.contains("BENCH_COLOR")?m.benchColor:"Unavailable"));}
 private String value(double n,int places,long received){return fresh(received)&&Double.isFinite(n)?String.format(Locale.US,"%."+places+"f",n):"Unavailable";}
 void showCalibration(){if(wizard!=null&&wizard.isShowing())return;LinearLayout p=a.vertical();p.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(8));p.addView(a.text("1 · Select trailer\n2 · Verify the real wired sensor\n3 · Capture a known empty/light scale weight when practical\n4 · Change load, enter its scale weight, and capture again\n5 · Verify against a scale",14,0xffedf3fa));a.addButton(p,a.button("Select trailer",this::chooseTrailer,false));wizardEnable=a.button("Enable real sensor",()->{if(a.isConnected()&&!m.bench)a.send("SENSOR_ENABLE|ON");},false);a.addButton(p,wizardEnable);wizardStatus=a.text("",13,0xffa2b1c4);p.addView(wizardStatus);p.addView(a.text("Known scale weight · lb (empty does not mean zero)",13,0xffedf3fa));known=new EditText(a);known.setTextColor(0xffedf3fa);known.setSingleLine(true);known.setInputType(2|8192);known.setHint("Weight from a real scale");p.addView(known);wizardCapture=a.button("Capture real pressure & scale weight",()->{String n=known.getText().toString().trim();double lb=Telemetry.number(n);if(!n.matches("[0-9]+(?:\\.[0-9]+)?")||!Double.isFinite(lb)||lb>10000000){known.setError("Enter a valid scale weight");return;}if(!canCapture()||!a.hasProfile()||capturePending){a.notice("Wait for a fresh, ready real sensor and exit bench mode.");return;}if(!SessionPolicy.separated(wizardTrailer.equals(m.profile)?lastCaptured:Double.NaN,m.psi)){a.notice("Change the load until pressure differs by at least 2 PSI from the last point captured in this session.");return;}pendingPsi=m.psi;pendingTrailer=m.profile;capturePending=true;captureSent=now();a.send("CAL_CAPTURE|"+n);update();},false);a.addButton(p,wizardCapture);p.addView(a.text("Existing points are preserved. Use meaningfully different pressures; this guide checks a 2 PSI difference between points captured here. Older saved point pressures are unavailable from the controller. Capture is always blocked for bench/simulated data. After at least two points, compare the estimated load with a real scale; add more points if needed.",12,0xffa2b1c4));ScrollView wrap=new ScrollView(a);wrap.addView(p);wizard=new AlertDialog.Builder(a).setTitle("Guided calibration").setView(wrap).setNegativeButton("Done",null).create();wizard.show();update();}
 void update(){if(status==null)return;String sensor=!a.isConnected()?"Unknown":!fresh(sensorAt)?"Stale":m.sensor.equals("NO_SIGNAL")?"No signal":m.sensor;String gps=!a.isConnected()?"Unknown":!fresh(gpsAt)?"Stale":m.gpsFix?"Fix":"Searching";status.setText("Sensor: "+sensor+"   ·   GPS: "+gps);compat.setText("App 0.7.0 · Controller: "+(a.isConnected()?m.firmware:"Unavailable")+"\n"+(a.isConnected()?SessionPolicy.compatibility(m):"Connect to check compatibility"));if(retrying&&!a.isConnected())a.say("connection","Reconnecting…");work.setText(pendingWork!=null?pendingWork.equals("WORK")?"Turning work lights on…":"Turning work lights off…":!fresh(lightsAt)?"Work lights · status unavailable":m.lightMode.equals("WORK")?"Work lights ON · tap to turn off":"Work lights OFF · tap to turn on");work.setEnabled(fresh(lightsAt)&&!m.bench&&pendingWork==null);a.selected(work,fresh(lightsAt)&&m.lightMode.equals("WORK"));for(int i=0;i<zones.size();i++){Button b=zones.get(i);b.setEnabled(a.isConnected()&&m.bench&&m.capabilities.contains("BENCH_ZONES"));a.selected(b,m.capabilities.contains("BENCH_ZONES")&&m.benchZone.equals(new String[]{"BOTH","1","2"}[i]));}for(Button b:testColors)b.setEnabled(a.isConnected()&&m.bench&&m.capabilities.contains("BENCH_COLOR"));diagnostics();if(wizard!=null&&wizard.isShowing()){wizardEnable.setEnabled(a.isConnected()&&!m.bench);wizardCapture.setEnabled(canCapture()&&a.hasProfile()&&!capturePending);wizardStatus.setText("Trailer: "+m.profile+"\nSaved points: "+m.points+" / 8\nReal sensor: "+sensor+" · "+value(m.psi,1,telemetryAt)+" PSI\nEstimated load: "+(fresh(telemetryAt)&&m.hasWeight()?String.format(Locale.US,"%,.0f lb",m.weight):"Unavailable until calibrated")+"\n"+(m.bench?"Exit bench mode to calibrate.":capturePending?"Waiting for controller confirmation…":m.points<2?"Capture at least two real scale points at different pressures.":"Verify the estimate against a real scale."));}}
 void tick(){if(pendingWork!=null&&now()-workSent>5000){pendingWork=null;lightsAt=0;a.notice("Work-light change was not confirmed. Reconnect or refresh status.");}if(capturePending&&now()-captureSent>5000){capturePending=false;a.notice("Capture confirmation unavailable. Refresh trailer data before trying again.");a.send("GET_STATUS");}if(a.isConnected()&&!fresh(gpsAt)){m.gpsFix=false;m.speed=m.distance=Double.NaN;}update();}
 void close(){closed=true;cancelRetry();handler.removeCallbacksAndMessages(null);a.unregisterReceiver(radio);if(wizard!=null)wizard.dismiss();}
}
